# cc-data.pl — surveys Claude Code session data, read only, and compares
# what one Claude Code version writes with what another one wrote.
#
# Usage: cc-data.pl [-c CONFIG_DIR] [-g CLAUDE_JSON] [-o FILE] BASE NEW
#   BASE  the version csm was checked with (e.g. 2.1.314)
#   NEW   the version to evaluate
#   -c    Claude Code configuration directory
#         (default $CLAUDE_CONFIG_DIR, else ~/.claude)
#   -g    global configuration file
#         (default $CLAUDE_CONFIG_DIR/.claude.json, else ~/.claude.json)
#   -o    also write the inventory of both versions to FILE
#
# Lines are counted for the version in their "version" field; lines
# without it (metadata records) for the version of the line before.
# Only lines of BASE and NEW are parsed, so a large history stays fast.
#
# Exit status: 0 nothing new, 1 differences or failed checks, 2 usage.

use strict;
use warnings;
use Getopt::Std;
use JSON::PP;

my %OPT;
getopts('c:g:o:', \%OPT) && @ARGV == 2
	or die "usage: cc-data.pl [-c CONFIG_DIR] [-g CLAUDE_JSON] [-o FILE] BASE NEW\n";
my ($BASE, $NEW) = @ARGV;
my $HOME = $ENV{HOME} // die "cc-data.pl: HOME is not set\n";
my $CONFIG = $OPT{c} // $ENV{CLAUDE_CONFIG_DIR} // "$HOME/.claude";
my $GLOBAL = $OPT{g} // (defined $ENV{CLAUDE_CONFIG_DIR} ? "$ENV{CLAUDE_CONFIG_DIR}/.claude.json" : "$HOME/.claude.json");
my $PROJECTS = "$CONFIG/projects";
my $CHUNK = 65536;
my $JSON = JSON::PP->new->allow_nonref;

# Fields csm knows to point into the session directory (prompt.md 3.2).
my %KNOWN_SESSION_FIELDS = map { $_ => 1 } (
	'toolUseResult.persistedOutputPath', 'tool_results_dir',
	'attachment.files[].path', 'attachment.filename', 'trackingPath',
	'realParentDir', 'toolUseResult.filePath', 'toolUseResult.file.filePath',
	'message.content[].input.file_path', 'wireToolInputs.*.file_path',
);

my %INV;       # version -> item -> count
my %LINES;     # version -> number of lines
my @PROBLEMS;  # failed checks, one sentence each
my %STATS;

# Directory name of a project path, as Claude Code makes it (3.2).
sub encode_name {
	my ($path) = @_;
	my $text = do {
		no warnings;
		my $copy = $path;
		utf8::decode($copy) ? $copy : join '', map { $_ < 128 ? chr $_ : "\x{FFFD}" } unpack 'C*', $path;
	};
	my (@units);
	for my $ch (split //, $text) {
		my $c = ord $ch;
		if ($c > 0xFFFF) {
			$c -= 0x10000;
			push @units, 0xD800 + ($c >> 10), 0xDC00 + ($c & 0x3FF);
		} else {
			push @units, $c;
		}
	}
	my $name = join '', map { ($_ < 128 && chr($_) =~ /[A-Za-z0-9]/) ? chr $_ : '-' } @units;
	return $name if length $name <= 200;
	my $h = 0;
	$h = ($h * 31 + $_) % 4294967296 for @units;
	$h -= 4294967296 if $h >= 2147483648;
	$h = -$h if $h < 0;
	my $b36 = '';
	do { $b36 = substr('0123456789abcdefghijklmnopqrstuvwxyz', $h % 36, 1) . $b36; $h = int($h / 36) } while $h > 0;
	return substr($name, 0, 200) . '-' . $b36;
}

# First and last 64 KiB, as Claude Code reads them.
sub head_tail {
	my ($file) = @_;
	open my $fh, '<:raw', $file or return;
	my $size = -s $fh;
	my ($head, $tail) = ('', '');
	read $fh, $head, $CHUNK;
	if ($size > $CHUNK) {
		seek $fh, $size - $CHUNK, 0;
		read $fh, $tail, $CHUNK;
	} else {
		$tail = $head;
	}
	close $fh;
	return ($head, $tail, $size);
}

# Complete lines of a fragment; a line cut by the fragment edge is
# dropped unless the edge is the end of the file.
sub lines_of {
	my ($text, $cut_start, $cut_end) = @_;
	my @l = split /\n/, $text, -1;
	shift @l if $cut_start;
	pop @l if $cut_end || (@l && $l[-1] eq '');
	return @l;
}

sub decode_line {
	my ($line) = @_;
	my $v = eval { $JSON->decode($line) };
	return ref $v eq 'HASH' ? $v : undef;
}

# Project path of a session file: last relocatedCwd in the tail, else
# the first cwd in the head.
sub project_path {
	my ($file) = @_;
	my ($head, $tail, $size) = head_tail($file);
	return unless defined $head;
	my $big = $size > $CHUNK;
	for my $l (reverse lines_of($tail, $big, 0)) {
		next unless index($l, '"relocatedCwd":') >= 0;
		my $o = decode_line($l) or next;
		return ($o->{relocatedCwd}, 'relocated')
		    if ($o->{type} // '') eq 'relocated' && defined $o->{relocatedCwd} && !ref $o->{relocatedCwd};
	}
	for my $l (lines_of($head, 0, $big)) {
		next unless index($l, '"cwd":') >= 0;
		my $o = decode_line($l) or next;
		return ($o->{cwd}, 'cwd') if defined $o->{cwd} && !ref $o->{cwd};
	}
	return;
}

# Key path with array indices and generated names folded.
sub fold_key {
	my ($k) = @_;
	return '*' if $k =~ /^toolu_|^[0-9a-f]{8}-|^\/|\s/ || $k !~ /^[A-Za-z_][\w-]*$/;
	return $k;
}

# Calls FN(path, string) for every string in V.
sub walk {
	my ($v, $path, $fn) = @_;
	if (ref $v eq 'HASH') {
		walk($v->{$_}, $path eq '' ? fold_key($_) : "$path." . fold_key($_), $fn) for keys %$v;
	} elsif (ref $v eq 'ARRAY') {
		walk($_, "$path\[]", $fn) for @$v;
	} elsif (defined $v && !ref $v) {
		$fn->($path, $v);
	}
}

sub add { $INV{$_[0]}{$_[1]}++ }

# One session file: inventory of the lines of BASE and NEW.
sub survey_file {
	my ($file, $sessdir, $project) = @_;
	open my $fh, '<:raw', $file or do { push @PROBLEMS, "cannot read $file: $!"; return };
	my ($ver, @pending);
	while (my $line = <$fh>) {
		chomp $line;
		if ($line =~ /"version":"([^"\\]{1,32})"/) {
			$ver = $1;
		}
		my $v = $ver;
		unless (defined $v) {
			push @pending, $line;
			next;
		}
		for my $l (@pending, $line) {
			$LINES{$v}++;
			next unless $v eq $BASE || $v eq $NEW;
			my $o = decode_line($l) or do { add($v, 'unparsed line') if length $l; next };
			my $type = $o->{type} // '(none)';
			add($v, "type $type");
			add($v, "key $type.$_") for keys %$o;
			walk($o, '', sub {
				my ($p, $s) = @_;
				add($v, "into-session-dir $p") if index($s, "$sessdir/") == 0;
				add($v, "project-path $type:$p")
				    if defined $project && $p !~ /^(?:message|toolUseResult|attachment|data|content)\b/
				    && ($s eq $project || index($s, "$project/") == 0);
			});
		}
		@pending = ();
	}
	close $fh;
}

# Shape of a directory entry, with generated names folded.
sub fold_entry {
	my ($rel) = @_;
	$rel =~ s/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/<uuid>/g;
	$rel =~ s/agent-[0-9a-z]+/agent-<id>/g;
	$rel =~ s/\btoolu_\w+/<tool>/g;
	$rel =~ s/\.superseded-\d+/.superseded-<time>/g;
	$rel =~ s{^memory/.+}{memory/<file>};
	$rel =~ s{/tool-results/.+}{/tool-results/<file>};
	return $rel;
}

sub list_tree {
	my ($dir, $rel, $out) = @_;
	opendir my $dh, $dir or return;
	for my $e (sort grep { $_ ne '.' && $_ ne '..' } readdir $dh) {
		my $p = "$dir/$e";
		my $r = $rel eq '' ? $e : "$rel/$e";
		if (-l $p) {
			$out->{fold_entry($r) . ' (symlink)'}++;
		} elsif (-d _) {
			$out->{fold_entry($r) . '/'}++;
			list_tree($p, $r, $out);
		} else {
			$out->{fold_entry($r)}++;
		}
	}
	closedir $dh;
}

# --- session directories --------------------------------------------------

opendir my $PD, $PROJECTS or die "cc-data.pl: $PROJECTS: $!\n";
my @DIRS = sort grep { !/^\./ && -d "$PROJECTS/$_" && !-l "$PROJECTS/$_" } readdir $PD;
closedir $PD;

my (%ENTRIES, $NEWEST, $NEWEST_TIME);
for my $d (@DIRS) {
	my $sessdir = "$PROJECTS/$d";
	list_tree($sessdir, '', \%ENTRIES);
	opendir my $dh, $sessdir or next;
	my @files = sort grep { /\.jsonl$/ && -f "$sessdir/$_" } readdir $dh;
	closedir $dh;
	my (%paths, $first_mismatch);
	for my $f (@files) {
		my $file = "$sessdir/$f";
		my $mt = (stat $file)[9];
		($NEWEST, $NEWEST_TIME) = ($file, $mt) if !defined $NEWEST_TIME || $mt > $NEWEST_TIME;
		my ($proj, $how) = project_path($file);
		$STATS{files}++;
		if (!defined $proj) {
			$STATS{'files without project path'}++;
		} else {
			$paths{$proj}++;
			$STATS{"project path from $how"}++;
			if ($how eq 'cwd' && encode_name($proj) ne $d) {
				push @PROBLEMS, "first cwd of $d/$f does not encode to its directory ($proj)";
			}
		}
		survey_file($file, $sessdir, $proj);
	}
	$STATS{'session directories'}++;
	$STATS{'directories without session files'}++ unless @files;
	my @match = grep { encode_name($_) eq $d } keys %paths;
	push @PROBLEMS, "no project path of $d encodes to its name (" . join(', ', sort keys %paths) . ')'
	    if %paths && !@match;
	$STATS{'long names (hash suffix)'}++ if length $d > 200;
	$STATS{'long names verified'}++ if length $d > 200 && @match;
}

# Version csm would read (4.8): last top-level "version" in the tail of
# the newest session file.
my $CSM_VERSION;
if (defined $NEWEST) {
	my ($head, $tail, $size) = head_tail($NEWEST);
	for my $l (reverse lines_of($tail, $size > $CHUNK, 0)) {
		my $o = decode_line($l) or next;
		if (defined $o->{version} && !ref $o->{version}) {
			$CSM_VERSION = $o->{version};
			last;
		}
	}
}

# --- global configuration -------------------------------------------------

my %CONFIG_KEYS;
if (open my $gf, '<:raw', $GLOBAL) {
	my $text = do { local $/; <$gf> };
	close $gf;
	my $g = eval { $JSON->decode($text) };
	if (ref $g ne 'HASH') {
		push @PROBLEMS, "$GLOBAL is not a JSON object";
	} else {
		$CONFIG_KEYS{$_} = 1 for keys %$g;
		my $p = $g->{projects};
		if (defined $p) {
			if (ref $p ne 'HASH') {
				push @PROBLEMS, 'projects is not an object';
			} else {
				my @rel = grep { !m{^/} } keys %$p;
				push @PROBLEMS, 'projects has keys that are not absolute paths: ' . join(', ', @rel) if @rel;
				$STATS{'projects keys'} = keys %$p;
			}
		}
		my $gh = $g->{githubRepoPaths};
		if (defined $gh) {
			if (ref $gh ne 'HASH') {
				push @PROBLEMS, 'githubRepoPaths is not an object';
			} else {
				for my $repo (sort keys %$gh) {
					push @PROBLEMS, "githubRepoPaths key $repo is not lower case owner/repo"
					    unless $repo =~ m{^[^/A-Z]+/[^/A-Z]+$};
					my $a = $gh->{$repo};
					if (ref $a ne 'ARRAY' || grep { ref || !m{^/} } @$a) {
						push @PROBLEMS, "githubRepoPaths $repo is not an array of absolute paths";
					}
				}
				$STATS{'githubRepoPaths repositories'} = keys %$gh;
			}
		}
	}
} else {
	push @PROBLEMS, "cannot read $GLOBAL: $!";
}

# --- report ---------------------------------------------------------------

print "Configuration: $CONFIG\nGlobal file:   $GLOBAL\n\n";
printf "  %-36s %s\n", $_, $STATS{$_} for sort keys %STATS;
printf "  %-36s %s\n", 'sessions-index.json files', $ENTRIES{'sessions-index.json'} // 0;
printf "  %-36s %s\n", 'version csm reads (4.8)', $CSM_VERSION // '-';
print "\nLines per version:\n";
printf "  %-12s %d\n", $_, $LINES{$_} for sort { vcmp($a, $b) } keys %LINES;

sub vcmp {
	my @a = split /[.+-]/, $_[0];
	my @b = split /[.+-]/, $_[1];
	while (@a || @b) {
		my ($x, $y) = (shift(@a) // '', shift(@b) // '');
		my $c = ($x =~ /^\d+$/ && $y =~ /^\d+$/) ? $x <=> $y : $x cmp $y;
		return $c if $c;
	}
	return 0;
}

print "\nSession directory entries:\n";
printf "  %6d  %s\n", $ENTRIES{$_}, $_ for sort keys %ENTRIES;

print "\nTop-level keys of the global file:\n  ", join(' ', sort keys %CONFIG_KEYS), "\n"
    if %CONFIG_KEYS;

my $DIFFS = 0;
my ($BI, $NI) = ($INV{$BASE} // {}, $INV{$NEW} // {});
print "\nNew in $NEW (not seen in $BASE):\n";
for my $k (sort keys %$NI) {
	next if $BI->{$k};
	my $mark = '';
	if ($k =~ /^into-session-dir (.*)/) {
		$mark = $KNOWN_SESSION_FIELDS{$1} ? '' : '  [not in prompt.md 3.2; csm rewrites it by prefix]';
	}
	printf "  %6d  %s%s\n", $NI->{$k}, $k, $mark;
	$DIFFS++;
}
print "\nSeen in $BASE, not in $NEW:\n";
for my $k (sort keys %$BI) {
	next if $NI->{$k};
	printf "  %6d  %s\n", $BI->{$k}, $k;
	$DIFFS++;
}
print "\nFields pointing into the session directory in $NEW:\n";
for my $k (sort grep { /^into-session-dir / } keys %$NI) {
	(my $f = $k) =~ s/^into-session-dir //;
	printf "  %6d  %s%s\n", $NI->{$k}, $f, $KNOWN_SESSION_FIELDS{$f} ? '' : '  [new to prompt.md 3.2]';
}

print "\nProblems:\n";
print "  $_\n" for @PROBLEMS;
print "  none\n" unless @PROBLEMS;
printf "\ncc-data: %d lines of %s, %d lines of %s, %d differences, %d problems\n",
    $LINES{$BASE} // 0, $BASE, $LINES{$NEW} // 0, $NEW, $DIFFS, scalar @PROBLEMS;

if ($OPT{o}) {
	open my $out, '>', $OPT{o} or die "cc-data.pl: $OPT{o}: $!\n";
	for my $v ($BASE, $NEW) {
		printf $out "%s\t%s\t%d\n", $v, $_, $INV{$v}{$_} for sort keys %{$INV{$v} // {}};
	}
	close $out;
}
exit(($DIFFS || @PROBLEMS) ? 1 : 0);
